// src/lib/mcp/tools/list-my-orders.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@3.4.0";
var list_my_orders_default = defineTool2({
  name: "list_my_orders",
  title: "Mes commandes",
  description: "List the signed-in user's 50 most recent orders (as buyer or seller) with status.",
  inputSchema: {},
  annotations: { readOnlyHint: true, openWorldHint: false },
  handler: async (_args, ctx) => {
    if (!ctx.isAuthenticated()) return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    const supabase = supabaseForUser(ctx);
    const uid = ctx.getUserId();
    const { data, error } = await supabase.from("orders").select("id, buyer_id, total_price, quantity, status, payment_status, delivery_status, created_at").order("created_at", { ascending: false }).limit(50);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const rows = (data ?? []).map((o) => ({
      id: o.id,
      role: o.buyer_id === uid ? "buyer" : "seller",
      total_price: Number(o.total_price),
      quantity: o.quantity,
      status: o.status,
      payment_status: o.payment_status ?? null,
      delivery_status: o.delivery_status ?? null,
      created_at: o.created_at
    }));
    return { content: [{ type: "text", text: JSON.stringify(rows) }], structuredContent: { orders: rows } };
  }
});

// src/lib/mcp/tools/get-wallet.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@3.4.0";
var get_wallet_default = defineTool3({
  name: "get_wallet",
  title: "Mon portefeuille",
  description: "Get the signed-in user's wallet balance and their 20 latest wallet transactions.",
  inputSchema: {},
  annotations: { readOnlyHint: true, openWorldHint: false },
  handler: async (_args, ctx) => {
    if (!ctx.isAuthenticated()) return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    const supabase = supabaseForUser(ctx);
    const [w, t] = await Promise.all([
      supabase.from("wallets").select("balance, total_earned, total_withdrawn").maybeSingle(),
      supabase.from("wallet_transactions").select("type, amount, description, status, created_at").order("created_at", { ascending: false }).limit(20)
    ]);
    if (w.error || t.error) return { content: [{ type: "text", text: (w.error ?? t.error).message }], isError: true };
    const wallet = w.data ? { balance: Number(w.data.balance), total_earned: Number(w.data.total_earned), total_withdrawn: Number(w.data.total_withdrawn) } : null;
    const transactions = (t.data ?? []).map((x) => ({
      type: x.type,
      amount: Number(x.amount),
      description: x.description ?? null,
      status: x.status,
      created_at: x.created_at
    }));
    return { content: [{ type: "text", text: JSON.stringify({ wallet, transactions }) }], structuredContent: { wallet, transactions } };
  }
});

